import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FaTachometerAlt,  FaCalendarAlt, FaEdit, FaChalkboardTeacher, FaSignOutAlt } from 'react-icons/fa';

const Nav = ({ isSidebarOpen }) => {
  const navigate = useNavigate();

  const handleLogout = () => {
    // Hapus token autentikasi dan role dari localStorage
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    // Redirect ke halaman login
    navigate('/login');
  };

  return (
    <aside className={`w-64 bg-teal-700 text-white flex-shrink-0 transition-all duration-300 ${isSidebarOpen ? 'block' : 'w-[83px]'}`}>
      <nav>
        <ul className="space-y-2 p-4">
          <li className='text-xl'>
            <a href="/dashboardMahasiswa" className="block px-4 py-2 rounded hover:bg-teal-600">
              <FaTachometerAlt className="inline-block mr-2" /> {isSidebarOpen && 'Dashboard'}
            </a>
          </li>
          <li className='text-xl'>
            <a href="/pembayaranMahasiswa" className="block px-4 py-2 rounded hover:bg-teal-600">
              <FaCalendarAlt className="inline-block mr-2" /> {isSidebarOpen && 'Keuangan'}
            </a>
          </li>
          <li className='text-xl'>
            <a href="/jadwalMahasiswa" className="block px-4 py-2 rounded hover:bg-teal-600">
              <FaChalkboardTeacher className="inline-block mr-2" /> {isSidebarOpen && 'Jadwal'}
            </a>
          </li>
          <li className='text-xl'>
            <a href="/absenMahasiswa" className="block px-4 py-2 rounded hover:bg-teal-600">
              <FaEdit className="inline-block mr-2" /> {isSidebarOpen && 'Presensi'}
            </a>
          </li>
          <li className='text-xl'>
            <button onClick={handleLogout} className="block w-full text-left px-4 py-2 rounded hover:bg-red-600 hover:text-white">
              <FaSignOutAlt className="inline-block mr-2" /> {isSidebarOpen && 'Logout'}
            </button>
          </li>
        </ul>
      </nav>
    </aside>
  );
};

export default Nav;
